function drawPortfolioMap(rows,line){var host=document.getElementById('case492Map');if(!host)return;if(!window.MAPCFG||!MAPCFG.apikey){host.innerHTML='<div class="case492-map-empty"><b>Карта готова к отображению</b><span>Добавьте API-ключ Яндекс Карт в настройках. Таблица и фильтры работают без ключа.</span></div>';return;}if(typeof loadYandexMaps!=='function'){host.innerHTML='<div class="case492-map-empty">Картографический модуль недоступен.</div>';return;}loadYandexMaps(function(){try{host.innerHTML='';var valid=rows.filter(function(p){return isFinite(n(p.lat))&&isFinite(n(p.lng));});var center=valid.length?[valid[0].lat,valid[0].lng]:[41.3,64.5];var map=new ymaps.Map(host,{center:center,zoom:valid.length>1?3:11,controls:['zoomControl','fullscreenControl']});var om=new ymaps.ObjectManager({clusterize:true,gridSize:64,clusterDisableClickZoom:false});om.objects.options.set({preset:line==='Leasing & Sales'?'islands#redCircleDotIcon':'islands#darkGreenCircleDotIcon'});valid.forEach(function(p){om.add({type:'Feature',id:p.id,geometry:{type:'Point',coordinates:[p.lat,p.lng]},properties:{iconCaption:p.name,balloonContentHeader:E(p.name),balloonContentBody:'<b>'+E(p.city)+', '+E(p.country)+'</b><br>'+E(p.category)+'<br>GBA: '+fmt(p.gba)+' м² · GLA: '+fmt(p.gla)+' м²<br><small>'+E((p.scope||[]).join(', '))+'</small><hr><b style="color:#9a6500">'+(p.verification==='verified'?'Координаты подтверждены':'Приблизительная точка города — требуется проверка')+'</b>'}});});map.geoObjects.add(om);if(valid.length>1){var bounds=om.getBounds();if(bounds)map.setBounds(bounds,{checkZoomRange:true,zoomMargin:38});}}catch(e){host.innerHTML='<div class="case492-map-empty">Не удалось построить карту: '+E(e.message||e)+'</div>';}});}
