window.case492CoordinateSave=function(id){var p=CASE_PORTFOLIO_PROJECTS.find(function(x){return x.id===id;});if(!p)return;var lat=n(document.getElementById('c492_lat').value),lng=n(document.getElementById('c492_lng').value),verified=document.getElementById('c492_verified').checked;if(lat<-90||lat>90||lng<-180||lng>180){alert('Проверьте координаты.');return;}p.lat=lat;p.lng=lng;p.verification=verified?'verified':'needs_review';p.coordinateAccuracy=verified?'exact_manual':'city_approximate';p.coordinateSource=document.getElementById('c492_coord_src').value.trim();p.verifiedAt=verified?new Date().toISOString():'';try{p.verifiedBy=(S.user&&S.user.name)||'';}catch(e){}save('Координаты проекта '+p.name);document.querySelector('.case492-modal-wrap').remove();go(UI.route);};

